# Try: convert all 3-cells that are not reachable from border via 4-connectivity through 3s
grid = [
    [0, 3, 3, 0, 3, 3, 3, 3, 3, 3, 3, 0, 3, 3],
    [3, 0, 3, 0, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [0, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 0],
    [3, 3, 0, 3, 3, 3, 0, 3, 0, 0, 0, 0, 3, 3],
    [0, 3, 3, 3, 3, 3, 3, 0, 0, 3, 0, 3, 3, 3],
    [0, 3, 3, 0, 0, 3, 3, 0, 3, 0, 0, 0, 3, 3],
    [3, 3, 3, 0, 3, 3, 0, 3, 3, 3, 0, 3, 3, 3],
    [3, 3, 3, 3, 0, 3, 0, 3, 3, 3, 3, 0, 3, 0],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 0, 3, 3],
    [3, 3, 3, 3, 3, 0, 3, 0, 3, 0, 0, 3, 3, 0],
    [0, 0, 3, 3, 3, 3, 0, 3, 0, 3, 3, 3, 3, 3],
    [0, 8, 3, 8, 8, 8, 8, 3, 3, 3, 3, 0, 3, 0],
    [3, 0, 8, 3, 3, 8, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 0, 8, 3, 3, 3, 3, 0, 0, 0, 3],
    [3, 3, 3, 3, 3, 3, 0, 3, 3, 3, 3, 3, 0, 3],
    [0, 0, 3, 0, 3, 0, 3, 3, 3, 3, 3, 3, 3, 3]
]

rows, cols = len(grid), len(grid[0])
from collections import deque

# Flood fill from ALL border cells (including corners)
queue = deque()
reachable_from_border = set()

# Add all border cells that are 3
for r in range(rows):
    for c in [0, cols-1]:
        if grid[r][c] == 3 and (r,c) not in reachable_from_border:
            queue.append((r,c))
            reachable_from_border.add((r,c))
    if grid[r][c] == 3:
        continue

for c in range(cols):
    for r in [0, rows-1]:
        if grid[r][c] == 3 and (r,c) not in reachable_from_border:
            queue.append((r,c))
            reachable_from_border.add((r,c))

# But also include all non-border interior 3s that could be starting points
# Actually, let's do it properly - start from every border cell and expand
queue = deque()
reachable_from_border = set()

# Collect all border 3s
border_3s = []
for r in range(rows):
    border_3s.extend([(r,c) for c in range(cols) if grid[r][c] == 3])
border_3s.extend([(r,c) for r in range(rows) for c in [0, cols-1] if grid[r][c] == 3 and (r,c) not in border_3s])

for r in range(rows):
    for c in [0, cols-1]:
        if grid[r][c] == 3:
            border_3s.append((r,c))

for c in range(cols):
    for r in [0, rows-1]:
        if grid[r][c] == 3:
            border_3s.append((r,c))

visited = set()
for pos in border_3s:
    visited.add(pos)
queue = deque(border_3s)

while queue:
    r, c = queue.popleft()
    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 3 and (nr, nc) not in visited:
            visited.add((nr, nc))
            queue.append((nr, nc))

print(f"Border-reachable 3s: {len(visited)}")

# Interior cells = 3s not reachable from border
interior_3s = {(r,c) for r in range(rows) for c in range(cols) 
               if grid[r][c] == 3 and (r,c) not in visited}
print(f"Interior 3s: {len(interior_3s)}")

result = []
for r in range(rows):
    row = []
    for c in range(cols):
        val = grid[r][c]
        if val == 8:
            row.append(8)
        elif (r,c) in interior_3s:
            row.append(8)
        else:
            row.append(val)
    result.append(row)

print(json.dumps({"action": "submit", "grid": result}))

